head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vRowCount = 0;
scwin.vMktCd = '';
scwin.vStrtDd = '';
scwin.vSelObj;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name searchClsDtl
 * @description 상장마감 종목정보 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchClsDtl = function() {
    let param = '';
    param += "&{P}V_BND_MKTACT_TP_CD=" + scwin.vMktCd;
    let qryId = '';
    if (scwin.processGp === '1') {
        qryId = scwin.getQryId();
        param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
        // 분할상환 전송관련 추가 JACKAL_190220
        param += "&{P}V_CLS_DD=" + edt_PrsntDd.getValue();
    } else if (scwin.processGp === '2') {
        qryId = scwin.getQryIdEnd();
        param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    }
    let dsNm = 'BNS_CLS_ISU_INFO';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_IsuList, dsNm, qryId, param);
};

/**
 * @method
 * @name searchSendData
 * @description 매매전송 종목정보 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchSendData = function() {
    let param = '';
    param += "&{P}V_CLS_DD=" + edt_BizClsDd.getValue();
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    let qryId = 'lds.stf.bnscls.select.listClsEndSendInfo';
    let dsNm = 'BNS_SEND_ISU_INFO';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_SendInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name searchSendData1
 * @description 매매전송 종목정보 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchSendData1 = function() {
    let param = '';
    param += "&{P}V_CLS_DD=" + edt_BizClsDd.getValue();
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    let qryId = 'lds.stf.bnscls.select.listClsEndSendInfo';
    let dsNm = 'BNS_SEND_ISU_INFO';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_SendInfo1, dsNm, qryId, param);
};

/**
 * @method
 * @name searchCls
 * @description 상장마감 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchCls = function() {
    let param = '';
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    // 분할상환 전송관련 추가 JACKAL_190220
    param += "&{P}V_CLS_DD=" + edt_PrsntDd.getValue();
    let dsNm = 'BNS_CLS_LIST';
    let qryId = 'lds.stf.bnscls.select.listCls';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_MktList, dsNm, qryId, param);
};

/**
 * @method
 * @name searchSendIsuInfo
 * @description 상장마감완료 전송정보 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchSendIsuInfo = function() {
    let param = '';
    param += "&{P}V_TASK_DD=" + edt_BizClsDd.getValue();
    let dsNm = 'BNS_CLS_SEND_INFO';
    let qryId = 'lds.stf.bnscls.select.listClsSendInfo';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_ClsSendInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name searchClsEnd
 * @description 상장마감한 데이터 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchClsEnd = function() {
    let param = '';
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    let dsNm = 'BNS_CLS_LIST';
    let qryId = 'lds.stf.bnscls.select.listClsEnd';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_MktList, dsNm, qryId, param);
};

/**
 * @method
 * @name searchClsDd
 * @description 마감일 데이터 조회한다.
 * @param {String} clsDd clsDd
 * @returns {void}
 * @hidden N
 */
scwin.searchClsDd = function(clsDd) {
    let param = '';
    param += "&{P}V_STRT_DD=" + clsDd;
    let dsNm = 'BNS_CHECK_CLS_DD';
    let qryId = 'lds.stf.bnscls.select.readChkClsDd';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckCls, dsNm, qryId, param);
};

/**
 * @method
 * @name clsProcs
 * @description 마감처리 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clsProcs = async function() {
    let param = '';
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    let dsNm = 'BNS_CHECK_CLS_PROC';
    let qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckClsProc, dsNm, qryId, param);

    // 채권마감이력 확인
    if (dts_CheckClsProc.getCellData(1, 'VALID_SEND_CFM') !== 'Y') {
        await $c.win.alert('시장조치내역생성 처리를 하십시오.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') === 'Y') {
        await $c.win.alert('업무마감작업이 이미 종료되었습니다.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "상장마감"))) return;
    let url = "/bns/ListCls.do?method=processCls";
    url += "&SCREN_ID=" + "ULDBNS30300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let param = "STRT_DD=" + edt_StrtDd.getValue();
    // 분할상환 전송관련 추가 JACKAL_190220
    param += ",CLS_DD=" + edt_PrsntDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name sendCfm
 * @description 전송내역 생성 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendCfm = async function() {
    // 발행기관 데이터 (종목명, 주소 등) 완성형한글 체크
    urlck += "&outputMessageId=BNS_CHECK_CLS_COMPLETE_KOREAN";
    urlck += "&STRT_DD=" + edt_StrtDd.getValue();
    dts_completeKorean.SyncLoad = "true";
    const sbmOptions = {
        id : "sbm_dts_completeKorean",
        action : "/bns/ListCls.do",
        ref : "",
        target : "dts_completeKorean=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const div = dts_completeKorean.getCellData(1, 'DIV');
    let isurCd = dts_completeKorean.getCellData(1, 'ISUR_CD');
    const comNm = dts_completeKorean.getCellData(1, 'COM_NM');
    const comAbbrv = dts_completeKorean.getCellData(1, 'COM_ABBRV');
    let msg = '';
    if (div === '1') {
        msg += ' 금일 발행기관 데이터에 문제가 있습니다.';
        msg += '\n\n 문제발생 발행기관코드 : ' + isurCd;
        msg += '\n 문제발생 발행기관명 : ' + comNm;
    } else if (div === '2') {
        msg += '금일 채권마스터 데이터에 문제가 있습니다.';
        msg += '\n\n 문제발생 표준코드 : ' + isurCd;
        msg += '\n 문제발생 한글종목명 : ' + comNm;
    }
    msg += '\n\n 시스템담당자에게 연락바랍니다.';
    msg += '\n\n 계속 진행하시겠습니까?';
    if (dts_completeKorean.getRowCount() > 0) {
        if (!window.confirm(msg)) {
            scwin.processGp = '1';
            return;
        }
    }
    let param = '';
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    let dsNm = 'BNS_CHECK_CLS_PROC';
    let qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckClsProc, dsNm, qryId, param);
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') === 'Y') {
        await $c.win.alert('업무마감작업이 이미 종료되었습니다.');
        return;
    }

    // 발행기관, 채권마스터 종목명에 엔터값 있는지 확인
    const stdCd = dts_CheckClsProc.getCellData(1, 'STD_CD');
    const stdCdAppl = dts_CheckClsProc.getCellData(1, 'STD_CD_APPL'); // jackal_140819 라인구분체크 추가
    let isurCd = dts_CheckClsProc.getCellData(1, 'ISUR_CD');
    let msg = '금일 발행기관, 채권마스터 데이터에 문제가 있습니다.';
    msg += '\n 문제발생 발행기관코드 : ' + isurCd;
    msg += '\n 문제발생 채권마스터코드 : ' + stdCd;
    msg += '\n 문제발생 신청마스터코드 : ' + stdCdAppl;
    msg += '\n 시스템담당자에게 연락바랍니다.';
    if (isurCd !== '' || stdCd !== '' || stdCdAppl !== '') {
        await $c.win.alert(msg);
        return;
    }

    // 금일 수신된 신용등급정보를 처리했는지 확인.
    if (dts_CheckClsProc.getCellData(1, 'HAS_CREDIT_RCV') === 'Y') {
        if (dts_CheckClsProc.getCellData(1, 'VALID_CREDIT_RCV') === 'Y') {
            await $c.win.alert('금일 수신된 신용등급정보를 처리하지 않았습니다.\n 신용평가 수신내역을 확인바랍니다.');
            return;
        }
    }
    // 스트립 통합처리 완료 확인.
    if (dts_CheckClsProc.getCellData(1, 'VALID_STRIP') === 'Y') {
        await $c.win.alert('마감처리 전 스트립 통합처리를 하시기 바랍니다.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_STRIP') === 'F') {
        await $c.win.alert("스트립 시장조치(스트립신규, 추가 및 재결합)와\n\n'스트립 통합처리' 화면내용이 불일치함.\n\n'스트립 통합처리'를 취소 후 다시 진행바람.");
        return;
    }

    // 종목중복체크
    qryId = 'lds.stf.bnscls.select.listCheckListIsuDupl';
    dts_CheckDup.SyncLoad = "true";
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckDup, dsNm, qryId, param);
    if (dts_CheckDup.getRowCount() > 0) {
        let dupMsg = '';
        for (let idx = 1; idx <= dts_CheckDup.getRowCount(); idx++) {
            dupMsg += dts_CheckDup.getCellData(idx, 'DUP_ISU') + '\n';
        }
        dupMsg += '로 중복조치되었습니다.\n확인 후 다시 처리하여 주십시오.';
        await $c.win.alert(dupMsg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "시장조치내역생성"))) return;
    let url = "/bns/ListCls.do?method=processSendCfm";
    url += "&SCREN_ID=" + "ULDBNS30300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let param = "STRT_DD=" + edt_StrtDd.getValue();
    // 분할상환 전송관련 추가 JACKAL_190220
    param += ",CLS_DD=" + edt_PrsntDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name reClsProcs
 * @description 재마감처리 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reClsProcs = async function() {
    scwin.processGp = '9';
    let param = '';
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    let dsNm = 'BNS_CHECK_CLS_PROC';
    let qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckClsProc, dsNm, qryId, param);

    // 채권마감이력 확인
    let msg = '';
    // 시장조치반영완료
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS1') === 'Y') {
        await $c.win.alert('이미 일일 시장조치반영이 완료 되었습니다.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') === 'Y') {
        msg += '채권송신(매매)데이타를 다시 생성하여 송신 할 경우에 해당합니다.';
        msg += '\n다음 데이타가 클리어(Delete)됩니다.';
        msg += '\n- 채권마감이력';
        msg += '\n- 시장조치 전송내역';
        msg += '\n- 신용평가 전송내역';
        await $c.win.alert(msg);
    } else {
        msg += '업무마감이 되지 않아 업무마감처리를';
        msg += '\n다시 하실수 없습니다.';
        await $c.win.alert(msg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "재마감처리"))) return;
    dts_SendInfo.removeAll();
    dts_List.removeAll();
    let url = "/bns/ListCls.do?method=reProcessCls";
    url += "&SCREN_ID=" + "ULDBNS30300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let param = "STRT_DD=" + edt_StrtDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name getParMktFile
 * @description 시장지파일 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParMktFile = function(arrPar) {
    arrPar[0] = {
        TRD_DD: edt_BizClsDd.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name getParIsuDtlAndMktactDtl
 * @description 시장조치상세내역 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDtlAndMktactDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_IsuList.getCellData(dts_IsuList.getRowPosition(), 'STD_CD'),
        STRT_DD: dts_IsuList.getCellData(dts_IsuList.getRowPosition(), 'STRT_DD')
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name intiIsuCol
 * @description 종목정보를 초기화한다.
 * @returns {void}
 * @hidden N
 */
scwin.intiIsuCol = function() {
    grd_IsuList.Redraw = false;
    scwin.showFalse();

    // 상호변경
    if (scwin.vMktCd === '201') scwin.show201();
    // 합병/회사분할

    else if (scwin.vMktCd === '202') scwin.show202();
    // 종목분할

    else if (scwin.vMktCd === '203') scwin.show202();
    // 변경상장종목분할

    else if (scwin.vMktCd === '105') scwin.show105();
    // BW 신주인수권행사

    else if (scwin.vMktCd === '205') scwin.show205();
    // BW 분리종목

    else if (scwin.vMktCd === '104') scwin.show104();
    // 일괄상장채권 상장금액조정(월별,일별) 301,320

    else if (scwin.vMktCd === '301' || scwin.vMktCd === '320') scwin.show301320();
    // 주식관련사채 권리행사 302

    else if (scwin.vMktCd === '302') scwin.show302();
    // 중도상환 303,304

    else if (scwin.vMktCd === '303' || scwin.vMktCd === '304') scwin.show303304();
    // 국고채추가발행 305

    else if (scwin.vMktCd === '305') scwin.show305();
    // 권리행사가액 변경 306

    else if (scwin.vMktCd === '306') scwin.show306();
    // 발행가액 변경 307

    else if (scwin.vMktCd === '307') scwin.show307();
    // 표면이자율,FRN 변동금리 변경 308, 309

    else if (scwin.vMktCd === '308' || scwin.vMktCd === '309') scwin.show308309();
    // 옵션상환일 변경 311

    else if (scwin.vMktCd === '311') scwin.show311();
    // 수동상장폐지 314

    else if (scwin.vMktCd === '314') scwin.show314();
    // 기타변경 316

    else if (scwin.vMktCd === '316') scwin.show316();
    // BW(일반사채)권리행사 315

    else if (scwin.vMktCd === '315') scwin.show315();
    // 분할상환정보 JACKAL_190220

    else if (scwin.vMktCd === '500') scwin.show500();
    // 자동상장폐지(상환일만기) 900

    else if (scwin.vMktCd === '900') scwin.show900();
    // 신용평가등급수신 321

    else if (scwin.vMktCd === '321') scwin.show321();
    // 스트립신규 401

    else if (scwin.vMktCd === '401') scwin.show401();
    // 스트립추가재결합 402

    else if (scwin.vMktCd === '402') scwin.show402();
    // 추가상장 및 스트립신규 403

    else if (scwin.vMktCd === '403') scwin.show403();
    // 추가상장 및 스트립추가 / 재결합, 스트립통합 404,405

    else if (scwin.vMktCd === '404' || scwin.vMktCd === '405') scwin.show404405();
    // WIT지정

    else if (scwin.vMktCd === '113') scwin.show113();
    // WIT종목정보확정

    else if (scwin.vMktCd === '330') scwin.show330();
    // default

    else {
        // 국채,지방채,특수채,회사채,외국채권 신규상장
        scwin.showDefault();
    }
    grd_IsuList.Redraw = true;
};

