/**********************************************
 * 함수명   : fn_SearchMktact
 * 설명       : 시장조치내역 조회한다.
 ***********************************************/
scwin.vStdCd;

/**
 * @method
 * @name searchMktact
 * @description search Mktact 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact = function() {
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
    param += "&{P}V_APPL_YN=N";
    // param += "&{P}V_STD_CD=KR6015861S58";

    let dsNm = 'BNS_MKTACT_DTL';
    let qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_List, dsNm, qryId, param);
};

/**********************************************
 * 함수명   : fn_SearchMktact1
 * 설명       : 시장조치내역 조회한다.
 ***********************************************/
scwin.vClsApplyYn;

/**
 * @method
 * @name searchMktact1
 * @description search Mktact1 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact1 = function() {
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    // param += "&{P}V_STD_CD=KR6015861S58";

    let dsNm = 'BNS_MKTACT_DTL';
    let qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    if (scwin.vClsApplyYn === 'Y') {
        param += "&{P}V_APPL_YN=Y";
    } else {
        param += "&{P}V_APPL_YN=N";
    }
    $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_List1, dsNm, qryId, param);
};

/**
 * @method
 * @name gform_onload
 * @description 숨기기
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 숨기기
    if (js_usr_tp_cd === '1') {
        // 운영자이면
        btn_ReClsProcs.show("");
    } else {
        btn_ReClsProcs.hide();
    }

    // 탭선택
    tab_List.setSelectedTabIndex(1);
    tab_ListCls.setSelectedTabIndex(1);
    tab_ListCls1.setSelectedTabIndex(1);

    // 패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Item2);
    $c.bns.BnsPanelToGroupBox(pnl_Cls);
    $c.bns.BnsPanelToGroupBox(pnl_ClsDtl);
    $c.bns.BnsPanelToGroupBox(pnl_SendDtl);
    $c.bns.BnsPanelToGroupBox(pnl_ClsDtl1);
    $c.bns.BnsPanelToGroupBox(pnl_SendDtl1);

    // 종목정보 컬럼 초기화
    scwin.intiIsuCol();

    // 마감조회
    scwin.processGp = '1';
    scwin.searchClsDd('');

    // 임시데이터셋설정

    // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Temp.insertRow();
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    if (edt_BizClsDd.getValue() === '') {
        await $c.win.alert('업무마감일을 입력 하십시오.');
        return;
    }
    scwin.processGp = '2';
    scwin.searchClsDd(edt_BizClsDd.getValue());
};

/**
 * @method
 * @name dts_MktList_OnLoadCompleted
 * @description dts_MktList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MktList_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    if (rowcount === 0) {
        dts_MktList.removeAll();
        dts_IsuList.removeAll();
        $c.cm.setColumnProp(grd_MktList, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
        if (scwin.processGp === '2') {
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
        }
    } else {
        // 최종호가,CD최종호가 조회
        // fn_SearchLastOrdYd();
        // 헤더설정
        if (scwin.processGp === '1') {
            $c.cm.setColumnProp(grd_MktList, 'BND_MKTACT_TP_NM', 'Name', "마감전 : 총 " + dts_MktList.getCellData(1, "TOT_MKTACT_CNT") + "건");
        } else {
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 " + dts_MktList.getCellData(1, "TOT_MKTACT_CNT") + "건");
        }
    }
    // 종목전송정보조회
    if (scwin.processGp === '2') {
        scwin.searchSendIsuInfo();
    }
};

