    await $c.win.alert(dts_MktList);
};

/**
 * @method
 * @name dts_MktList_OnRowPosChanged
 * @description Mkt List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_MktList_OnRowPosChanged = function(row) {
    dts_IsuList.removeAll();
    if (row === 0) return;
    scwin.vMktCd = dts_MktList.getCellData(row, 'BND_MKTACT_TP_CD');
    const cnt = dts_MktList.getCellData(row, "MKTACT_CNT");

    // 종목헤더설정
    if (scwin.processGp === '1') {
        scwin.intiIsuCol();
    }

    // 종목조회
    if (cnt > 0) {
        scwin.searchClsDtl();
    }
};

