/**
 * @method
 * @name dts_CheckCls_OnLoadCompleted
 * @description dts_CheckCls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CheckCls_OnLoadCompleted = async function(rowcount) {
    if (edt_BizClsDd.getValue() === '') {
        edt_BizClsDd.setValue(dts_CheckCls.getCellData(1, 'PRSNT_DD'));
    }
    if (scwin.processGp === '1') {
        edt_PrsntDd.setValue(dts_CheckCls.getCellData(1, 'PRSNT_DD'));
        edt_StrtDd.setValue(dts_CheckCls.getCellData(1, 'CLS_DD'));
        scwin.vStrtDd = edt_StrtDd.getValue();
        scwin.searchSendData();
        let param = '';
        param += "&{P}V_STRT_DD=" + edt_StrtDd.getValue();
        let dsNm = 'BNS_CHECK_CLS_PROC';
        let qryId = 'lds.stf.bnscls.select.readChkClsProc';
        dts_CheckClsProc.SyncLoad = "true";
        $c.bns.fn_SearchBns("ULDBNS30300.xml", dts_CheckClsProc, dsNm, qryId, param);
        if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') === 'Y') {
            txb_ClsDtl.setValue('* 마감처리 완료');
        } else if (dts_CheckClsProc.getCellData(1, 'VALID_SEND_CFM') === 'Y') {
            txb_ClsDtl.setValue('* "상장마감"이 완료되지 않았습니다. 상장마감 시 "시장조치내역생성" 후 "상장마감" 하시기 바랍니다.');
            tab_ListCls.setSelectedTabIndex(2);
        } else {
            txb_ClsDtl.setValue('* "상장마감"이 완료되지 않았습니다. 상장마감 시 "시장조치내역생성" 후 "상장마감" 하시기 바랍니다.');
        }
        scwin.searchCls();
    } else if (scwin.processGp === '2') {
        if (dts_CheckCls.getCellData(1, "VALID_BIZ_CLS_DD") === "Y") {
            await $c.win.alert("업무마감일이 아닙니다.");
            dts_MktList.removeAll();
            dts_SendInfo1.removeAll();
            dts_List1.removeAll();
            dts_ClsSendInfo.removeAll();
            dts_IsuList.removeAll();
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
            return;
        }
        scwin.searchClsEnd();
